package authn

import (
	"context"
	"encoding/binary"
	"encoding/json"
	"errors"
	"io"
	"net"
	"sync"
	"time"

	"github.com/aonsyed/cyberpanel/platform/internal/identity"
)

const ProtocolVersion uint16 = 1
const MaximumFrameBytes = 4 << 20

type Operation string
const (
	OperationEnrollPassword Operation="enroll_password";OperationVerifyPassword Operation="verify_password";OperationIssueAPIKey Operation="issue_api_key";OperationVerifyAPIKey Operation="verify_api_key";OperationBeginTOTP Operation="begin_totp";OperationConfirmTOTP Operation="confirm_totp";OperationVerifyTOTP Operation="verify_totp";OperationVerifyRecovery Operation="verify_recovery";OperationBeginWebAuthnRegistration Operation="begin_webauthn_registration";OperationFinishWebAuthnRegistration Operation="finish_webauthn_registration";OperationBeginWebAuthnAssertion Operation="begin_webauthn_assertion";OperationFinishWebAuthnAssertion Operation="finish_webauthn_assertion";OperationVerifyWebAuthn Operation="verify_webauthn";OperationRevoke Operation="revoke"
)

type Request struct{Version uint16 `json:"version"`;ID string `json:"id"`;Operation Operation `json:"operation"`;Deadline time.Time `json:"deadline"`;Payload json.RawMessage `json:"payload"`}
type Response struct{Version uint16 `json:"version"`;ID string `json:"id"`;Operation Operation `json:"operation"`;Payload json.RawMessage `json:"payload,omitempty"`;Error string `json:"error,omitempty"`;CompletedAt time.Time `json:"completed_at"`}
type EnrollPasswordRequest struct{Principal identity.ID `json:"principal"`;Password []byte `json:"password"`};type RefResult struct{Ref identity.ID `json:"ref"`};type VerifyRequest struct{Ref identity.ID `json:"ref"`;Secret []byte `json:"secret"`};type VerifyResult struct{Verified bool `json:"verified"`};type APIKeyIssueRequest struct{Principal identity.ID `json:"principal"`;Scopes []identity.Permission `json:"scopes"`;Expires time.Time `json:"expires"`};type APIKeyIssueResult struct{Ref identity.ID `json:"ref"`;Raw []byte `json:"raw"`};type APIKeyVerifyRequest struct{Raw []byte `json:"raw"`};type APIKeyVerifyResult struct{Ref identity.ID `json:"ref"`;Verified bool `json:"verified"`};type TOTPBeginRequest struct{Principal identity.ID `json:"principal"`};type TOTPBeginResult struct{Ref identity.ID `json:"ref"`;Secret []byte `json:"secret"`;RecoveryCodes []string `json:"recovery_codes"`};type CodeRequest struct{Ref identity.ID `json:"ref"`;Code string `json:"code"`};type WebAuthnBeginRequest struct{Principal identity.ID `json:"principal"`;RPID string `json:"rp_id"`};type WebAuthnBeginResult struct{Ref identity.ID `json:"ref"`;Options json.RawMessage `json:"options"`};type WebAuthnFinishRequest struct{Ref identity.ID `json:"ref"`;Response json.RawMessage `json:"response"`};type WebAuthnFinishResult struct{Ref identity.ID `json:"ref"`;PublicData json.RawMessage `json:"public_data,omitempty"`;Verified bool `json:"verified,omitempty"`}

type RoundTripper interface{RoundTrip(context.Context,Request)(Response,error)}
type Client struct{transport RoundTripper;clock func()time.Time}
func NewClient(transport RoundTripper)(*Client,error){if transport==nil{return nil,ErrInvalid};return &Client{transport:transport,clock:time.Now},nil}
func(client *Client)call(ctx context.Context,operation Operation,input,target any)error{if client==nil||client.transport==nil||ctx==nil||!validOperation(operation){return ErrUnavailable};payload,err:=json.Marshal(input);if err!=nil{return err};now:=client.clock().UTC();deadline:=now.Add(30*time.Second);if current,ok:=ctx.Deadline();ok&&current.Before(deadline){deadline=current};id,err:=newReference("arq");if err!=nil{wipe(payload);return err};request:=Request{Version:ProtocolVersion,ID:id.String(),Operation:operation,Deadline:deadline,Payload:payload};response,err:=client.transport.RoundTrip(ctx,request);wipe(payload);if err!=nil{return err};if response.Version!=ProtocolVersion||response.ID!=request.ID||response.Operation!=operation||response.CompletedAt.Before(now.Add(-time.Minute))||response.CompletedAt.After(client.clock().UTC().Add(time.Minute)){return ErrUnavailable};if response.Error!=""{return protocolError(response.Error)};if target==nil{if len(response.Payload)!=0&&string(response.Payload)!="{}"{return ErrUnavailable};return nil};return strictJSON(response.Payload,target)}
func(client *Client)EnrollPassword(ctx context.Context,principal identity.ID,password []byte)(identity.ID,error){request:=EnrollPasswordRequest{principal,password};defer wipe(request.Password);var result RefResult;err:=client.call(ctx,OperationEnrollPassword,&request,&result);return result.Ref,err}
func(client *Client)VerifyPassword(ctx context.Context,ref identity.ID,password []byte)(bool,error){request:=VerifyRequest{ref,password};defer wipe(request.Secret);var result VerifyResult;err:=client.call(ctx,OperationVerifyPassword,&request,&result);return result.Verified,err}
func(client *Client)IssueAPIKey(ctx context.Context,principal identity.ID,scopes []identity.Permission,expires time.Time)(identity.ID,[]byte,error){var result APIKeyIssueResult;err:=client.call(ctx,OperationIssueAPIKey,&APIKeyIssueRequest{principal,scopes,expires},&result);return result.Ref,result.Raw,err}
func(client *Client)VerifyAPIKey(ctx context.Context,raw []byte)(identity.ID,bool,error){request:=APIKeyVerifyRequest{raw};defer wipe(request.Raw);var result APIKeyVerifyResult;err:=client.call(ctx,OperationVerifyAPIKey,&request,&result);return result.Ref,result.Verified,err}
func(client *Client)BeginTOTPEnrollment(ctx context.Context,principal identity.ID)(identity.ID,[]byte,[]string,error){var result TOTPBeginResult;err:=client.call(ctx,OperationBeginTOTP,&TOTPBeginRequest{principal},&result);return result.Ref,result.Secret,result.RecoveryCodes,err}
func(client *Client)ConfirmTOTPEnrollment(ctx context.Context,ref identity.ID,code string)error{return client.call(ctx,OperationConfirmTOTP,&CodeRequest{ref,code},&struct{}{})}
func(client *Client)VerifyTOTP(ctx context.Context,ref identity.ID,code string)(bool,error){var result VerifyResult;err:=client.call(ctx,OperationVerifyTOTP,&CodeRequest{ref,code},&result);return result.Verified,err}
func(client *Client)VerifyRecoveryCode(ctx context.Context,ref identity.ID,code string)(bool,error){var result VerifyResult;err:=client.call(ctx,OperationVerifyRecovery,&CodeRequest{ref,code},&result);return result.Verified,err}
func(client *Client)BeginWebAuthnRegistration(ctx context.Context,principal identity.ID,rpID string)(identity.ID,[]byte,error){var result WebAuthnBeginResult;err:=client.call(ctx,OperationBeginWebAuthnRegistration,&WebAuthnBeginRequest{principal,rpID},&result);return result.Ref,append([]byte(nil),result.Options...),err}
func(client *Client)FinishWebAuthnRegistration(ctx context.Context,ref identity.ID,response []byte)([]byte,error){request:=WebAuthnFinishRequest{ref,append([]byte(nil),response...)};defer wipe(request.Response);var result WebAuthnFinishResult;err:=client.call(ctx,OperationFinishWebAuthnRegistration,&request,&result);return append([]byte(nil),result.PublicData...),err}
func(client *Client)BeginWebAuthnAssertion(ctx context.Context,principal identity.ID,rpID string)(identity.ID,[]byte,error){var result WebAuthnBeginResult;err:=client.call(ctx,OperationBeginWebAuthnAssertion,&WebAuthnBeginRequest{principal,rpID},&result);return result.Ref,append([]byte(nil),result.Options...),err}
func(client *Client)FinishWebAuthnAssertion(ctx context.Context,challenge identity.ID,response []byte)(identity.ID,bool,error){request:=WebAuthnFinishRequest{challenge,append([]byte(nil),response...)};defer wipe(request.Response);var result WebAuthnFinishResult;err:=client.call(ctx,OperationFinishWebAuthnAssertion,&request,&result);return result.Ref,result.Verified,err}
func(client *Client)VerifyWebAuthn(ctx context.Context,ref identity.ID,response []byte)(bool,error){request:=WebAuthnFinishRequest{ref,append([]byte(nil),response...)};defer wipe(request.Response);var result VerifyResult;err:=client.call(ctx,OperationVerifyWebAuthn,&request,&result);return result.Verified,err}
func(client *Client)Revoke(ctx context.Context,ref identity.ID)error{return client.call(ctx,OperationRevoke,&RefResult{ref},&struct{}{})}

type Handler struct{Verifier *Verifier}
func(handler Handler)Handle(ctx context.Context,request Request)(Response,error){if handler.Verifier==nil||ctx==nil||validateRequest(request,handler.Verifier.now())!=nil{return Response{},ErrUnavailable};defer wipe(request.Payload);reply:=Response{Version:ProtocolVersion,ID:request.ID,Operation:request.Operation,CompletedAt:handler.Verifier.now()};encode:=func(value any)error{raw,err:=json.Marshal(value);reply.Payload=raw;return err};var err error;switch request.Operation{case OperationEnrollPassword:var value EnrollPasswordRequest;if err=decodePayload(request.Payload,&value);err==nil{var ref identity.ID;ref,err=handler.Verifier.EnrollPassword(ctx,value.Principal,value.Password);wipe(value.Password);if err==nil{err=encode(RefResult{ref})}};case OperationVerifyPassword:var value VerifyRequest;if err=decodePayload(request.Payload,&value);err==nil{var ok bool;ok,err=handler.Verifier.VerifyPassword(ctx,value.Ref,value.Secret);wipe(value.Secret);if err==nil{err=encode(VerifyResult{ok})}};case OperationIssueAPIKey:var value APIKeyIssueRequest;if err=decodePayload(request.Payload,&value);err==nil{var ref identity.ID;var raw []byte;ref,raw,err=handler.Verifier.IssueAPIKey(ctx,value.Principal,value.Scopes,value.Expires);if err==nil{err=encode(APIKeyIssueResult{ref,raw});wipe(raw)}};case OperationVerifyAPIKey:var value APIKeyVerifyRequest;if err=decodePayload(request.Payload,&value);err==nil{var ref identity.ID;var ok bool;ref,ok,err=handler.Verifier.VerifyAPIKey(ctx,value.Raw);wipe(value.Raw);if err==nil{err=encode(APIKeyVerifyResult{ref,ok})}};case OperationBeginTOTP:var value TOTPBeginRequest;if err=decodePayload(request.Payload,&value);err==nil{var ref identity.ID;var secret []byte;var recovery []string;ref,secret,recovery,err=handler.Verifier.BeginTOTPEnrollment(ctx,value.Principal);if err==nil{err=encode(TOTPBeginResult{ref,secret,recovery});wipe(secret)}};case OperationConfirmTOTP:var value CodeRequest;if err=decodePayload(request.Payload,&value);err==nil{err=handler.Verifier.ConfirmTOTPEnrollment(ctx,value.Ref,value.Code);value.Code="";if err==nil{err=encode(struct{}{})}};case OperationVerifyTOTP:var value CodeRequest;if err=decodePayload(request.Payload,&value);err==nil{var ok bool;ok,err=handler.Verifier.VerifyTOTP(ctx,value.Ref,value.Code);value.Code="";if err==nil{err=encode(VerifyResult{ok})}};case OperationVerifyRecovery:var value CodeRequest;if err=decodePayload(request.Payload,&value);err==nil{var ok bool;ok,err=handler.Verifier.VerifyRecoveryCode(ctx,value.Ref,value.Code);value.Code="";if err==nil{err=encode(VerifyResult{ok})}};case OperationBeginWebAuthnRegistration,OperationBeginWebAuthnAssertion:var value WebAuthnBeginRequest;if err=decodePayload(request.Payload,&value);err==nil{var ref identity.ID;var options []byte;if request.Operation==OperationBeginWebAuthnRegistration{ref,options,err=handler.Verifier.BeginWebAuthnRegistration(ctx,value.Principal,value.RPID)}else{ref,options,err=handler.Verifier.BeginWebAuthnAssertion(ctx,value.Principal,value.RPID)};if err==nil{err=encode(WebAuthnBeginResult{ref,options})}};case OperationFinishWebAuthnRegistration,OperationFinishWebAuthnAssertion:var value WebAuthnFinishRequest;if err=decodePayload(request.Payload,&value);err==nil{if request.Operation==OperationFinishWebAuthnRegistration{var public []byte;public,err=handler.Verifier.FinishWebAuthnRegistration(ctx,value.Ref,value.Response);if err==nil{err=encode(WebAuthnFinishResult{Ref:value.Ref,PublicData:public});wipe(public)}}else{var ref identity.ID;var ok bool;ref,ok,err=handler.Verifier.FinishWebAuthnAssertion(ctx,value.Ref,value.Response);if err==nil{err=encode(WebAuthnFinishResult{Ref:ref,Verified:ok})}};wipe(value.Response)};case OperationVerifyWebAuthn:var value WebAuthnFinishRequest;if err=decodePayload(request.Payload,&value);err==nil{var ok bool;ok,err=handler.Verifier.VerifyWebAuthn(ctx,value.Ref,value.Response);wipe(value.Response);if err==nil{err=encode(VerifyResult{ok})}};case OperationRevoke:var value RefResult;if err=decodePayload(request.Payload,&value);err==nil{err=handler.Verifier.Revoke(ctx,value.Ref);if err==nil{err=encode(struct{}{})}};default:err=ErrInvalid};if err!=nil{reply.Error=errorCode(err);reply.Payload=nil};reply.CompletedAt=handler.Verifier.now();return reply,nil}
func decodePayload(raw []byte,target any)error{return strictJSON(raw,target)}

type ConnectionDialer interface{DialContext(context.Context)(net.Conn,error)}
type FramedTransport struct{Dialer ConnectionDialer}
func(transport FramedTransport)RoundTrip(ctx context.Context,request Request)(Response,error){if transport.Dialer==nil{return Response{},ErrUnavailable};connection,err:=transport.Dialer.DialContext(ctx);if err!=nil{return Response{},err};defer connection.Close();stop:=context.AfterFunc(ctx,func(){_=connection.SetDeadline(time.Now())});defer stop();if err=connection.SetDeadline(request.Deadline);err!=nil{return Response{},err};if err=writeFrame(connection,request);err!=nil{return Response{},err};var response Response;if err=readFrame(connection,&response);err!=nil{return Response{},err};return response,nil}
type PeerAuthorizer interface{Authorize(net.Conn)error}
type Server struct{Authorizer PeerAuthorizer;Handler Handler;MaximumConcurrent uint32;semaphore chan struct{};once sync.Once}
func(server *Server)Serve(listener net.Listener)error{if server==nil||listener==nil||server.Authorizer==nil||server.Handler.Verifier==nil{return ErrUnavailable};server.once.Do(func(){maximum:=server.MaximumConcurrent;if maximum==0{maximum=128};if maximum>2048{maximum=2048};server.semaphore=make(chan struct{},maximum)});for{connection,err:=listener.Accept();if err!=nil{return err};select{case server.semaphore<-struct{}{}:go func(){defer func(){<-server.semaphore;connection.Close()}();server.serve(connection)}();default:_=connection.Close()}}}
func(server *Server)serve(connection net.Conn){if server.Authorizer.Authorize(connection)!=nil{return};now:=server.Handler.Verifier.now();_=connection.SetReadDeadline(now.Add(10*time.Second));var request Request;if readFrame(connection,&request)!=nil||validateRequest(request,now)!=nil{return};_=connection.SetDeadline(request.Deadline);ctx,cancel:=context.WithDeadline(context.Background(),request.Deadline);defer cancel();response,_:=server.Handler.Handle(ctx,request);_=writeFrame(connection,response)}
func writeFrame(writer io.Writer,value any)error{raw,err:=json.Marshal(value);if err!=nil||len(raw)==0||len(raw)>MaximumFrameBytes{return ErrInvalid};var header [4]byte;binary.BigEndian.PutUint32(header[:],uint32(len(raw)));if err=writeAll(writer,header[:]);err!=nil{return err};return writeAll(writer,raw)}
func readFrame(reader io.Reader,target any)error{var header [4]byte;if _,err:=io.ReadFull(reader,header[:]);err!=nil{return err};size:=binary.BigEndian.Uint32(header[:]);if size==0||size>MaximumFrameBytes{return ErrInvalid};raw:=make([]byte,size);if _,err:=io.ReadFull(reader,raw);err!=nil{return err};return strictJSON(raw,target)}
func writeAll(writer io.Writer,value []byte)error{for len(value)>0{written,err:=writer.Write(value);if err!=nil{return err};if written<=0||written>len(value){return io.ErrShortWrite};value=value[written:]};return nil}
func errorCode(err error)string{switch{case errors.Is(err,ErrInvalid):return"invalid";case errors.Is(err,ErrNotFound):return"not_found";case errors.Is(err,ErrLocked):return"locked";case errors.Is(err,ErrConflict):return"conflict";case errors.Is(err,ErrReplay):return"replay";default:return"unavailable"}}
func protocolError(code string)error{switch code{case"invalid":return ErrInvalid;case"not_found":return ErrNotFound;case"locked":return ErrLocked;case"conflict":return ErrConflict;case"replay":return ErrReplay;default:return ErrUnavailable}}
func validOperation(operation Operation)bool{switch operation{case OperationEnrollPassword,OperationVerifyPassword,OperationIssueAPIKey,OperationVerifyAPIKey,OperationBeginTOTP,OperationConfirmTOTP,OperationVerifyTOTP,OperationVerifyRecovery,OperationBeginWebAuthnRegistration,OperationFinishWebAuthnRegistration,OperationBeginWebAuthnAssertion,OperationFinishWebAuthnAssertion,OperationVerifyWebAuthn,OperationRevoke:return true;default:return false}}
func validateRequest(request Request,now time.Time)error{if request.Version!=ProtocolVersion||!validOperation(request.Operation)||request.ID==""||len(request.Payload)==0||len(request.Payload)>MaximumFrameBytes{return ErrInvalid};id,err:=identity.NewID(request.ID);if err!=nil||!id.Valid()||request.Deadline.IsZero()||!request.Deadline.After(now)||request.Deadline.After(now.Add(5*time.Minute)){return ErrInvalid};return nil}
var _ identity.AuthVerifier=(*Client)(nil);var _ identity.WebAuthnLoginVerifier=(*Client)(nil);var _ identity.RecoveryCodeVerifier=(*Client)(nil)
